CREATE TABLE public.blog_articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, banner text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '{}', images jsonb NOT NULL DEFAULT '[]', collaborators jsonb NOT NULL DEFAULT '[]', projects text[] NOT NULL DEFAULT '{}', publish_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_articles TO anon, authenticated;
GRANT ALL ON public.blog_articles TO service_role;
ALTER TABLE public.blog_articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published articles are public" ON public.blog_articles FOR SELECT TO anon, authenticated USING (publish_at <= now());
CREATE TABLE public.blog_collaborators (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, avatar text NOT NULL DEFAULT '', label text NOT NULL);
GRANT SELECT ON public.blog_collaborators TO anon, authenticated;
GRANT ALL ON public.blog_collaborators TO service_role;
ALTER TABLE public.blog_collaborators ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Editorial signatures are public" ON public.blog_collaborators FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.blog_project_tags (project_id text PRIMARY KEY, color_start text NOT NULL, color_end text NOT NULL, gradient boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.blog_project_tags TO anon, authenticated;
GRANT ALL ON public.blog_project_tags TO service_role;
ALTER TABLE public.blog_project_tags ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Project tags are public" ON public.blog_project_tags FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.admin_gate_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_gate_attempts TO service_role;
ALTER TABLE public.admin_gate_attempts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_admin_attempt(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO admin_gate_attempts(key, attempts, reset_at) VALUES (_key, 1, now() + interval '15 minutes') ON CONFLICT (key) DO UPDATE SET attempts = CASE WHEN admin_gate_attempts.reset_at < now() THEN 1 ELSE admin_gate_attempts.attempts + 1 END, reset_at = CASE WHEN admin_gate_attempts.reset_at < now() THEN now() + interval '15 minutes' ELSE admin_gate_attempts.reset_at END RETURNING attempts INTO n; RETURN n <= 10; END; $$;
REVOKE ALL ON FUNCTION public.consume_admin_attempt(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_admin_attempt(text) TO service_role;